package net.civeira.phylax.feature.observe.observedissuealias.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;
import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.observe.observedissue.domain.ObservedIssueReference;

class IssueVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property issue of observed issue alias ")
  void test_issue_v_o_builder() {
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertEquals("10", IssueVO.fromReference("10").getIssueUid(),
        "The builder must store the reference value");
    Assertions.assertEquals("11", IssueVO.tryFromReference("11").getIssueUid(),
        "The builder must store the reference value");
    Assertions.assertEquals("12", IssueVO.tryFromReference("12", fails).getIssueUid(),
        "The builder must store the reference value");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertThrows(ConstraintException.class, () -> IssueVO.tryFrom(null));
    Assertions.assertEquals(ObservedIssueReference.of("one"),
        IssueVO.from(ObservedIssueReference.of("one")).getIssue());
    Assertions.assertThrows(ConstraintException.class, () -> IssueVO.tryFrom(new Object() {}));
    Assertions.assertEquals("[" + ObservedIssueReference.of("one") + "]",
        IssueVO.from(ObservedIssueReference.of("one")).toString());
  }
}
